import java.lang.ref.ReferenceQueue;
import java.lang.ref.WeakReference;

public class ReachabilityDemo {
    public static void main(String[] args) throws InterruptedException {
        byte[] heavyData = new byte[1024 * 1024 * 10]; // 10MB allocation
        ReferenceQueue<byte[]> queue = new ReferenceQueue<>();
        WeakReference<byte[]> weakRef = new WeakReference<>(heavyData, queue);

        System.out.println("Before dropping strong reference: " + weakRef.get());

        // Drop the only strong reference to heavyData
        heavyData = null;

        // Suggest garbage collection (non-deterministic)
        System.gc();
        Thread.sleep(100);

        System.out.println("After GC and dropping strong reference: " + weakRef.get());
        if (queue.poll() != null) {
            System.out.println("Object has been garbage collected and enqueued.");
        }
    }
}
